static int utilityHubPathJoin(char *path, char *filename, char *out, size_t outlen) {
    size_t plen, flen;
    if (!path || !filename || !out || outlen == 0) {
        utilHub.path_err = 1;
        return 0;
    }
    plen = strlen(path);
    flen = strlen(filename);
    if (plen + flen + 2 > outlen) {
        utilHub.path_err = 1;
        return 0;
    }
    memcpy(out, path, plen);
    if (plen > 0 && path[plen - 1] != '/') {
        out[plen] = '/';
        plen++;
    }
    memcpy(out + plen, filename, flen);
    out[plen + flen] = '\0';
    utilHub.path_err = 0;
    return 1;
}

